// "Kanban" => "Kanban",
// "Id of the tracker the board is a partial representation of" => "Id of the tracker the board is a partial representation of",
// "Card title field" => "Card title field",
// "Tracker field containing the inline editable text shown on each card" => "Tracker field containing the inline editable text shown on each card",
// "e.g. \"kanbanTitle\"" => "e.g. \"kanbanTitle\"",
// "Card description field" => "Card description field",
